(function attachFamilyDocumentsGoogleDrive(global){
  "use strict";
  const scope="https://www.googleapis.com/auth/drive.file",baseUrl="https://api-familydocuments.servicehub.co.nz/drive",allowed=new Set(["application/pdf","image/jpeg","image/png"]);let loading=null;
  const config=()=>global.familyPassportGoogleDriveConfig||{};
  const configured=()=>Boolean(config().clientId);
  function loadScript(){if(global.google?.accounts?.oauth2)return Promise.resolve();if(loading)return loading;loading=new Promise((resolve,reject)=>{const s=document.createElement("script");s.src="https://accounts.google.com/gsi/client";s.async=true;s.onload=resolve;s.onerror=()=>reject(new Error("Google authorization could not load."));document.head.append(s)});return loading}
  async function request(path,{method="GET",body=null,csrf=false,retry=true}={}){const token=global.familyPassportAuth.getAccessToken();if(!token)throw new Error("Sign in is required.");const response=await fetch(`${baseUrl}${path}`,{method,headers:{authorization:`Bearer ${token}`,...(body?{"content-type":"application/json"}:{}),...(csrf?{"x-requested-with":"XmlHttpRequest"}:{})},body:body?JSON.stringify(body):null}),value=await response.json().catch(()=>({}));if(response.status===401&&retry){await global.familyPassportAuth.refreshSession();return request(path,{method,body,csrf,retry:false})}if(!response.ok){const error=new Error(({mfa_and_admin_required:"Verify MFA as a household owner or Family Admin first.",drive_reconnect_required:"Google Drive authorization expired. Ask a household admin to reconnect it.",google_authorization_failed:"Google did not provide offline access. Remove Family Documents from Google account permissions, then reconnect."})[value.error]||"Google Drive could not complete that request.");error.code=value.error||"drive_failed";error.status=response.status;throw error}return value}
  async function connect(){if(!configured())throw Object.assign(new Error("Google Drive is not configured by the app owner."),{code:"drive_not_configured"});await loadScript();return new Promise((resolve,reject)=>{const client=global.google.accounts.oauth2.initCodeClient({client_id:config().clientId,scope,ux_mode:"popup",select_account:true,callback:async response=>{if(response.error)return reject(new Error(response.error_description||"Google authorization was not granted."));try{resolve(await request("/connect",{method:"POST",body:{code:response.code},csrf:true}))}catch(error){reject(error)}},error_callback:error=>reject(Object.assign(new Error("Google authorization was cancelled or blocked."),{code:error.type||"popup_failed"}))});client.requestCode()})}
  const folders=()=>request("/folders");
  const createFolder=name=>request("/folders",{method:"POST",body:{name:String(name||"").trim()}});
  const selectFolder=id=>request("/folders/select",{method:"POST",body:{id}});
  async function upload(file){if(!allowed.has(file.type)||file.size<1||file.size>5*1024*1024)throw new Error("Choose a JPEG, PNG or PDF smaller than 5 MB.");const bytes=new Uint8Array(await file.arrayBuffer());let raw="";for(let i=0;i<bytes.length;i+=0x8000)raw+=String.fromCharCode(...bytes.subarray(i,i+0x8000));return request("/upload",{method:"POST",body:{name:file.name,mime_type:file.type,content_base64:btoa(raw)}})}
  const removeCreated=(id,receipt)=>id&&receipt?request(`/files/${encodeURIComponent(id)}?receipt=${encodeURIComponent(receipt)}`,{method:"DELETE"}):Promise.resolve();
  async function openDocument(document){const value=await request("/open",{method:"POST",body:{document}}),bytes=Uint8Array.from(atob(value.content_base64),c=>c.charCodeAt(0));return {fileName:value.file_name,blob:new Blob([bytes],{type:value.mime_type})}}
  const disconnect=()=>request("/disconnect",{method:"POST",body:{}});
  global.familyPassportGoogleDrive=Object.freeze({scope,configured,connect,folders,createFolder,selectFolder,upload,removeCreated,openDocument,disconnect});
})(window);
